#include <iostream>
#include <memory>
#include <utility>
struct Nodo {
    long long valore;
    std::unique_ptr<Nodo> next;
    explicit Nodo(long long v) : valore(v) {}
};
int main() {
    int n; std::cin >> n;
    std::unique_ptr<Nodo> testa;
    for (int i = 0; i < n; ++i) {
        long long v; std::cin >> v;
        auto nuovo = std::make_unique<Nodo>(v);
        nuovo->next = std::move(testa);
        testa = std::move(nuovo); // Trasferimento di ownership.
    }
    long long somma = 0; int contati = 0;
    for (auto* p = testa.get(); p; p = p->next.get()) {
        somma += p->valore; ++contati;
    }
    std::cout << contati << " " << somma << "\n";
    // Il distruttore di unique_ptr libera la catena all’uscita.
}

